command:
sudo -n install -d -o root -g root -m 0750 /var/log/inventory
sudo -n tee /etc/rsyslog.d/20-inventory-collector.conf >/dev/null <<'ANTRIEB_EOF'
module(load="imtcp")
input(type="imtcp" port="514" ruleset="inventory_remote")

ruleset(name="inventory_remote") {
    if ($fromhost-ip == '10.100.184.11' and $programname == 'inventory') then {
        action(type="omfile" file="/var/log/inventory/node2.log" fileCreateMode="0640" dirCreateMode="0750")
        stop
    }
}
ANTRIEB_EOF
sudo -n rsyslogd -N1

